import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';

ReactDOM.render(
    <App />,
    document.getElementById('app'),
);

import React from 'react';
import modelGuitar from './functions/modelGuitar';
import styles from './css/styles.scss';
import removeNonNotes from './functions/removeNonNotes';

class GuitarView extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            guitar: new modelGuitar(),
        };

        this.handleNotesSelected = this.handleNotesSelected.bind(this);
    }

    handleNotesSelected(value) {
        this.state.guitar.findNotesInStrings(removeNonNotes(value.split('')));
        this.forceUpdate();
    }
    render() {
        return (
            <React.Fragment>
                <table className="GuitarView" style={styles}>
                    <tbody>
                        {this.state.guitar.strings.map((string, index) => (
                            <tr key={index}>
                                {string.map((note, i) => (
                                    <td key={i}>
                                        {note.highlight
                                            ? <b>{note.note}</b>
                                            : <span>{note.note}</span>
                                        }
                                    </td>
                                ))}
                            </tr>
                        ))}
                        <tr>
                            {this.state.guitar.strings[0].map((n, index) => (
                                <td key={index}>
                                    {this.state.guitar.dots.includes(index) && '.'}
                                </td>
                            ))}
                        </tr>
                    </tbody>
                </table>
                <input
                    type="text"
                    onChange={({ target }) => this.handleNotesSelected(target.value)}
                />
            </React.Fragment>
        );
    }
}

module.exports = GuitarView;

import notes from '../globals/notes';

export default (tuning, { topFret }) => (
    tuning.map((rootNote) => {
        const stringNotes = [];
        let noteIndex = notes.findIndex(note => note === rootNote);
        for (let i = 0; i < (topFret + 1); i += 1) {
            stringNotes.push({
                note: notes[noteIndex],
            });
            /**
             * If we're at the end of the note array, go back to the start
             */
            noteIndex = noteIndex === notes.length - 1
                ? 0
                : noteIndex + 1;
        }
        return stringNotes;
    })
);
